import math

def is_perfect_square(k):
    if k < 0:
        return False
    sqrt_k = int(math.sqrt(k))
    return sqrt_k * sqrt_k == k

def is_cool(n):
    """
    Tests if n is a cool integer using backtracking.
    """

    # State: (current_sum, used_mask)
    # used_mask is a bitmask where the i-th bit is 1 if (i+1) has been used.

    # The search function tries to complete the permutation.
    def backtrack(current_sum, used_mask, length):
        if length == n:
            return True

        # Try appending every available number k (from 1 to n)
        for k in range(1, n + 1):
            # Check if k is unused (i.e., (k-1)-th bit is 0)
            if not (used_mask & (1 << (k - 1))):

                next_sum = current_sum + k

                # Constraint check: Prefix sum must not be a perfect square
                if not is_perfect_square(next_sum):

                    # Recurse: Use k, update mask, increase length
                    new_mask = used_mask | (1 << (k - 1))
                    if backtrack(next_sum, new_mask, length + 1):
                        return True

        return False

    # Start the search. Initial sum is 0, nothing used (mask 0), length 0.
    return backtrack(0, 0, 0)

# Test for n = 1 to 20
results = {}
for n in range(1, 21):
    results[n] = is_cool(n)

# Collect the cool integers
cool_integers = [n for n, is_cool_val in results.items() if is_cool_val]

print(f"Results for n=1 to 20: {results}")
print(f"Sequence of cool integers: {cool_integers}")

