    if n < 0:
        return False
    sqrt_n = int(math.isqrt(n))
    return sqrt_n * sqrt_n == n

def check_cool_candidate(n):
    # 1. n >= 2 (Based on W1, n=1 is not cool)
    if n < 2:
        return False

    # 2. Necessary Condition 1: S_n must not be a square.
    Sn = n * (n + 1) // 2
    if is_perfect_square(Sn):
        return False

    # 3. Necessary Condition 2 (Heuristic): n must not be divisible by 6.
    if n % 6 == 0:
        return False

    # Additional known exclusion from W1/W3: n=8
    if n == 8:
        return False

    return True

